import React, { useState } from 'react';
import './Ahorro.css'; // Asegúrate de tener los estilos actualizados

const Ahorro = () => {
    const [objectives, setObjectives] = useState([]);
    const [savingsPlan, setSavingsPlan] = useState([]);

    const handleAddObjective = () => {
        setObjectives([...objectives, { amount: '', term: 'mensual', quantity: '' }]);
    };

    const handleObjectiveChange = (index, field, value) => {
        const newObjectives = [...objectives];
        newObjectives[index][field] = value;
        setObjectives(newObjectives);
    };

    const calculateSavingsPlan = () => {
        const plan = objectives.map((objective) => {
            const { amount, term, quantity } = objective;
            const targetAmount = parseFloat(amount);
            const quantityNumber = parseFloat(quantity);

            if (isNaN(targetAmount) || isNaN(quantityNumber) || quantityNumber <= 0) {
                return null;
            }

            let periods = 0;
            let savingsPerPeriod = 0;
            let periodType = ''; // Variable para definir si son meses o días

            switch (term) {
                case 'mensual':
                    periods = Math.ceil(targetAmount / quantityNumber);
                    savingsPerPeriod = quantityNumber;
                    periodType = 'Meses'; // Mostrar "Meses"
                    break;
                case 'semanal':
                    periods = Math.ceil(targetAmount / (quantityNumber * 4)); // Aproximadamente 4 semanas en un mes
                    savingsPerPeriod = quantityNumber * 4;
                    periodType = 'Meses'; // Se considera en términos de meses
                    break;
                case 'diario':
                    periods = Math.ceil(targetAmount / (quantityNumber * 30)); // Aproximadamente 30 días en un mes
                    savingsPerPeriod = quantityNumber * 30;
                    periodType = 'Días'; // Mostrar "Días"
                    break;
                default:
                    return null;
            }

            return { targetAmount, periods, savingsPerPeriod, periodType }; // Devuelve el tipo de período
        }).filter(Boolean);

        setSavingsPlan(plan);
    };

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <table>
                    <thead>
                        <tr>
                            <th>Cantidad Objetivo</th>
                            <th>Plazo</th>
                            <th>Ahorros por Plazo</th>
                        </tr>
                    </thead>
                    <tbody>
                        {objectives.map((objective, index) => (
                            <tr key={index}>
                                <td>
                                    <input
                                        type="number"
                                        placeholder="Cantidad"
                                        value={objective.amount}
                                        onChange={(e) => handleObjectiveChange(index, 'amount', e.target.value)}
                                    />
                                </td>
                                <td>
                                    <select
                                        value={objective.term}
                                        onChange={(e) => handleObjectiveChange(index, 'term', e.target.value)}
                                    >
                                        <option value="mensual">Mensual</option>
                                        <option value="semanal">Semanal</option>
                                        <option value="diario">Diario</option>
                                    </select>
                                </td>
                                <td>
                                    <input
                                        type="number"
                                        placeholder="Ahorro por período"
                                        value={objective.quantity}
                                        onChange={(e) => handleObjectiveChange(index, 'quantity', e.target.value)}
                                    />
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                <button onClick={handleAddObjective}>Agregar Objetivo</button>
                <button onClick={calculateSavingsPlan}>Calcular Plan de Ahorro</button>

                {/* Mostrar el plan de ahorros generado */}
                {savingsPlan.length > 0 && (
                    <div className="savings-plan">
                        <h2>Plan de Ahorro</h2>
                        <ul>
                            {savingsPlan.map((plan, index) => (
                                <li key={index}>
                                    Objetivo: ${plan.targetAmount} - {plan.periodType}: {plan.periods} - Ahorros por {plan.periodType.toLowerCase()}: ${plan.savingsPerPeriod}
                                </li>
                            ))}
                        </ul>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Ahorro;
